excels.excel:

EXPORT WITH SHEET="区域销售对比", HEADER=true,
    MAPPING={"a":"大区","b":"城市","c":"销售额"},
    FORMAT={"c":"#,##0.00"},
    FORMULAS={C5:'SUM(C2:C4)',C8:'SUM(C6:C7)',C11:'SUM(C9:C10)',C12:'C5+C8+C11'},
    STYLE={
        ROW 5:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right},
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right},
        ROW 11:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right},
        ROW 12:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right}
    },
    MERGE:{
        RANGE A2:A4 WITH MERGE_WITH_FIRST,
        RANGE A6:A7 WITH MERGE_WITH_FIRST,
        RANGE A9:A10 WITH MERGE_WITH_FIRST
    }
